mapper.select:
/* masterMpSoPayRegMngUploadPopPoSearch */ SELECT PODT.BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER) AS BUYER_NAME, (SELECT IRS_NO FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER) AS BUYER_IRS_NO, MAX(POHD.AGENT) AS AGENT, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_NAME, MAX((SELECT IRS_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_IRS_NO, PODT.PO_NO, PODT.PO_SEQ, MAX(PODT.BUYER_ITEM_NO) AS BUYER_ITEM_NO, MAX((SELECT PR_NO FROM ICOMPRDT PR WHERE PR.BUYER = PODT.BUYER AND PR.PR_NO = PODT.PR_NO AND PR.PR_SEQ = PODT.PR_SEQ)) AS PR_NO, MAX((SELECT PR_SEQ FROM ICOMPRDT PR WHERE PR.BUYER = PODT.BUYER AND PR.PR_NO = PODT.PR_NO AND PR.PR_SEQ = PODT.PR_SEQ)) AS PR_SEQ, MAX(NVL(GRDT.GR_NO, ' ')) AS GR_NO, MAX(NVL(GRDT.GR_SEQ,' ')) AS GR_SEQ, MAX(NVL(GRDT.GR_DATE, ' ')) AS GR_DATE, MAX(PODT.DESCRIPTION) || '/' || MAX(PODT.SPECIFICATION) AS ITEM_INFO FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMGRDT GRDT WHERE 1=1
AND PODT.BUYER IN ( SELECT COM_CODE FROM ICOMCMPY WHERE REPLACE(IRS_NO,'-','') = REPLACE(#{BUYER_IRS_NO},'-',''))
AND PODT.BUYER = #{st_buyer}
AND PODT.PO_NO LIKE '%'|| #{st_po_no} ||'%' AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND PODT.BUYER = GRDT.BUYER(+) AND PODT.PO_NO = GRDT.PO_NO(+) AND PODT.PO_SEQ = GRDT.PO_SEQ(+)
AND PODT.PO_SEQ = #{PO_SEQ}
AND PODT.BUYER_ITEM_NO LIKE '%'|| #{st_buyer_item_no} ||'%'
GROUP BY PODT.BUYER, PODT.PO_NO, PODT.PO_SEQ

mapper.update:

				 /*deleteMasterMpSoPayRegMngUploadPopExcel_select*/  
                DELETE PAY_REG_MNG_UPLOAD           
                WHERE ADD_USER_ID = #{st_user_id}
                AND   BUYER = #{BUYER}
                AND   PO_NO = #{PO_NO}
                AND   PO_SEQ = #{PO_SEQ}
